// Violates 1NF: repeating groups in a single column
// orders(id, customer, items) where items = 'book,pen,paper'

// 1NF: atomic values, no repeating groups
// orders(id, customer_id)
// order_items(order_id, item_id, quantity)

// Violates 2NF: partial dependency on composite key
// order_items(order_id, item_id, item_name, quantity)
// item_name depends only on item_id, not the full composite key

// 2NF: remove partial dependencies
// order_items(order_id, item_id, quantity)  -- depends on full key
// items(item_id, item_name, price)          -- item_name moved here

// Violates 3NF: transitive dependency
// employees(emp_id, dept_id, dept_name)
// dept_name depends on dept_id, not directly on emp_id

// 3NF: remove transitive dependencies
// employees(emp_id, dept_id)
// departments(dept_id, dept_name)

// BCNF: every determinant must be a candidate key
// teaching(student, subject, teacher)
// If teacher -> subject (a teacher teaches only one subject),
// teacher is a determinant but not a candidate key -- violates BCNF
// Solution: teacher(teacher, subject) + enrollment(student, teacher)

-- B-tree index: supports =, <, >, BETWEEN, LIKE 'prefix%'
CREATE INDEX idx_orders_customer ON orders(customer_id);

-- Composite index: column order matters
-- Good for WHERE customer_id = ? AND status = ?
-- Also usable for WHERE customer_id = ? alone (leading column)
-- NOT usable for WHERE status = ? alone
CREATE INDEX idx_orders_customer_status ON orders(customer_id, status);

-- Covering index: avoids heap fetch entirely
-- Query: SELECT status, total FROM orders WHERE customer_id = ?
CREATE INDEX idx_orders_covering ON orders(customer_id) INCLUDE (status, total);

-- Partial index: only indexes rows matching a condition
CREATE INDEX idx_active_orders ON orders(customer_id)
WHERE status = 'ACTIVE';

-- Hash index: equality-only, faster for = but no range support
CREATE INDEX idx_session_token ON sessions USING HASH (token);

-- GIN index: for full-text search and JSONB
CREATE INDEX idx_products_tags ON products USING GIN (tags);

// JPA: declare indexes on the @Table annotation
@Entity
@Table(name = "orders",
    indexes = {
        @Index(name = "idx_orders_customer_status",
               columnList = "customer_id, status")
    })
public class Order {
    @Id private Long id;
    private Long customerId;
    private String status;
    private BigDecimal total;
}

-- Simple junction table (composite primary key)
CREATE TABLE student_courses (
    student_id BIGINT REFERENCES students(id),
    course_id  BIGINT REFERENCES courses(id),
    PRIMARY KEY (student_id, course_id)
);

-- Rich junction table with its own attributes and surrogate PK
CREATE TABLE enrollments (
    id          BIGSERIAL PRIMARY KEY,
    student_id  BIGINT NOT NULL REFERENCES students(id),
    course_id   BIGINT NOT NULL REFERENCES courses(id),
    enrolled_at TIMESTAMP NOT NULL DEFAULT now(),
    grade       CHAR(2),
    UNIQUE (student_id, course_id)
);

// JPA: simple @ManyToMany mapping
@Entity
public class Student {
    @Id @GeneratedValue private Long id;
    private String name;

    @ManyToMany
    @JoinTable(
        name = "student_courses",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

// JPA: rich junction as a dedicated @Entity (preferred when attributes exist)
@Entity
public class Enrollment {
    @Id @GeneratedValue private Long id;

    @ManyToOne
    @JoinColumn(name = "student_id")
    private Student student;

    @ManyToOne
    @JoinColumn(name = "course_id")
    private Course course;

    private LocalDateTime enrolledAt;
    private String grade;
}

// Conceptual shard routing in Java
public class ShardRouter {
    private static final int SHARD_COUNT = 4;
    private final Map<Integer, DataSource> shards;

    // Hash-based shard key on userId
    public DataSource getShardForUser(long userId) {
        int shardId = (int) (userId % SHARD_COUNT);
        return shards.get(shardId);
    }

    // Range-based shard key on created_date
    // Shard 0: 2020, Shard 1: 2021, Shard 2: 2022, Shard 3: 2023+
    public DataSource getShardForOrder(LocalDate createdDate) {
        int year = createdDate.getYear();
        int shardId = Math.min(year - 2020, SHARD_COUNT - 1);
        return shards.get(shardId);
    }
}

// Spring AbstractRoutingDataSource for transparent shard routing
public class ShardingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // Set via ThreadLocal before each request
        return ShardContext.getCurrentShardId();
    }
}

// Anti-pattern: cross-shard join (avoid at all costs)
// SELECT * FROM shard1.orders o JOIN shard2.customers c ON o.customer_id = c.id
// Requires application-level join across multiple network calls

// HikariCP configuration via application.properties (Spring Boot)
spring.datasource.url=jdbc:postgresql://localhost:5432/mydb
spring.datasource.username=app
spring.datasource.password=secret
spring.datasource.hikari.maximum-pool-size=10
spring.datasource.hikari.minimum-idle=5
spring.datasource.hikari.connection-timeout=30000
spring.datasource.hikari.idle-timeout=600000
spring.datasource.hikari.max-lifetime=1800000
spring.datasource.hikari.keepalive-time=60000

// Java config equivalent
@Bean
public DataSource dataSource() {
    HikariConfig config = new HikariConfig();
    config.setJdbcUrl("jdbc:postgresql://localhost:5432/mydb");
    config.setUsername("app");
    config.setPassword("secret");
    // Formula: (cpu_cores * 2) + disk_spindles -- often 10-20
    config.setMaximumPoolSize(10);
    config.setMinimumIdle(5);
    config.setConnectionTimeout(30_000);   // max wait for a connection from pool
    config.setMaxLifetime(1_800_000);      // rotate before DB enforces idle timeout
    config.addDataSourceProperty("cachePrepStmts", "true");
    config.addDataSourceProperty("prepStmtCacheSize", "250");
    return new HikariDataSource(config);
}

