-- Schema with soft delete column
CREATE TABLE orders (
    id          BIGSERIAL PRIMARY KEY,
    customer_id BIGINT NOT NULL REFERENCES customers(id),
    total       DECIMAL(12,2) NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    deleted_at  TIMESTAMP  -- NULL means active; non-NULL means soft-deleted
);

-- Partial index: only index active records, keeping index lean
CREATE INDEX idx_orders_customer_active
    ON orders(customer_id)
    WHERE deleted_at IS NULL;

-- Partial unique constraint: allow re-registration after soft delete
CREATE UNIQUE INDEX idx_users_email_active
    ON users(email)
    WHERE deleted_at IS NULL;

// JPA Entity with automatic filter (Hibernate 6.x)
@Entity
@Table(name = "orders")
@SQLRestriction("deleted_at IS NULL")
public class Order {
    @Id @GeneratedValue private Long id;
    private Long customerId;
    private BigDecimal total;
    private LocalDateTime createdAt;
    private LocalDateTime deletedAt;  // null = active
}

// Soft delete service method
@Service
@Transactional
public class OrderService {
    public void softDelete(Long orderId) {
        Order order = orderRepository.findById(orderId)
            .orElseThrow(() -> new EntityNotFoundException(orderId.toString()));
        order.setDeletedAt(LocalDateTime.now());
        // Dirty checking commits the update automatically
    }

    // To access deleted records, bypass @SQLRestriction with a native query
    @Query(value = "SELECT * FROM orders WHERE id = :id", nativeQuery = true)
    Optional<Order> findByIdIncludeDeleted(@Param("id") Long id);
}

// Pattern 1: Optimistic locking with @Version to detect stale writes
@Entity
public class Product {
    @Id @GeneratedValue private Long id;
    private int stockCount;

    @Version  // Hibernate increments on every update; throws OptimisticLockException if stale
    private Long version;
}

// Pattern 2: Read-your-writes -- after write, return the saved object without re-querying
@Service
public class UserProfileService {
    public UserProfile updateEmail(Long userId, String newEmail) {
        UserProfile profile = repository.findById(userId).orElseThrow();
        profile.setEmail(newEmail);
        repository.save(profile);
        return profile;  // Return the object we just saved, not a replica read
    }
}

// Pattern 3: Idempotent event processing with deduplication
@Service
public class OrderEventConsumer {
    public void processOrderCreated(OrderCreatedEvent event) {
        if (idempotencyStore.exists(event.getEventId())) {
            log.info("Duplicate event {}, skipping", event.getEventId());
            return;
        }
        orderService.createOrder(event.toOrder());
        idempotencyStore.markProcessed(event.getEventId());
    }
}

// Pattern 4: Cache invalidation on write to avoid serving stale data
@Service
public class ProductCacheService {
    public void updateProduct(Product product) {
        productRepository.save(product);
        // Invalidate so next read fetches fresh data from DB
        cache.delete("product:" + product.getId());
    }
}
